for (let n = 1; n <= 5; n++) {
  console.log(n % 2 === 0 ? `${n} é par` : `${n} é ímpar`)
}

for (let i = 1; i <= 15; i++) {
  if (i % 15 === 0) console.log('FizzBuzz')
  else if (i % 3 === 0) console.log('Fizz')
  else if (i % 5 === 0) console.log('Buzz')
  else console.log(i)
}

function dobro(n) {
  return n * 2
}
console.log(dobro(4))
console.log(dobro(21))
